<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$in=messenger_input();$id=(int)($in['message_id']??0);$m=Database::fetch('SELECT conversation_id FROM chat_messages WHERE id=?',[$id]);if(!$m)throw new DomainException('پیام پیدا نشد.',404);MessengerSecurity::participant((int)$m['conversation_id'],(int)$u['id']);Database::execute('UPDATE chat_message_status SET status=IF(status="read","read","delivered"),delivered_at=COALESCE(delivered_at,NOW()) WHERE message_id=? AND user_id=?',[$id,(int)$u['id']]);return ['delivered'=>true];},true);
